// WARSAW REMONT — zdjęcia i obsługa formularza
// Linki Instagram i Threads są uzupełnione. Wstaw własne adresy Telegramu i Facebooka poniżej.
const projectPhotos = [
  'data:image/jpeg;base64,',
  'data:image/jpeg;base64,',
  'data:image/jpeg;base64,'
];
projectPhotos.forEach((src, i) => {
  const img = document.getElementById(`project-photo-${i + 1}`);
  if (img) img.src = src;
});

// Uzupełnij, jeśli korzystasz z tych profili:
const socialLinks = {
  telegram: "", // np. https://t.me/twojprofil
  facebook: ""  // np. https://facebook.com/twojprofil
};
Object.entries(socialLinks).forEach(([network, url]) => {
  const link = document.querySelector(`[data-social="${network}"]`);
  if (!link) return;
  if (url) link.href = url;
  else link.addEventListener("click", event => {
    event.preventDefault();
    alert("Dodaj adres profilu " + network + " w pliku script.js.");
  });
});

const form = document.getElementById("lead-form");
form?.addEventListener("submit", event => {
  event.preventDefault();
  const data = new FormData(form);
  const name = String(data.get("name") || "").trim();
  const reply = String(data.get("reply") || "").trim();
  const message = String(data.get("message") || "").trim();
  const body = `Dzień dobry, proszę o kontakt w sprawie remontu.\n\nImię i nazwisko: ${name}\nKontakt: ${reply}\nSzczegóły: ${message}`;
  const smsUrl = `sms:+48519465199?body=${encodeURIComponent(body)}`;
  window.location.href = smsUrl;
});
